-- Ecuador: ES/DE/FR milestone translations for the 6 milestones in
-- migration 379. Hand-translated, not machine copy-paste.

-- ec-first-mandate-2014
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-first-mandate-2014', 'es', 'La Resolución NAC-DGERCGC14-00790 introduce la validación de facturación electrónica en tiempo real', 'El 3 de septiembre de 2014 (publicada el 2 de octubre de 2014), el Servicio de Rentas Internas (SRI) de Ecuador emitió la Resolución NAC-DGERCGC14-00790, que sustituyó al esquema piloto voluntario de 2012 (Resolución NAC-DGERCGC12-00105) por una obligación real y vinculante para grupos designados de contribuyentes de transmitir facturas electrónicas al SRI para su validación mediante servicios web en el mismo momento en que se realiza la transacción. Este es el origen del mandato ecuatoriano de facturación electrónica casi en tiempo real, vigente desde entonces -- el antiguo esquema de 2012 solo pudo seguir utilizándose hasta el 31 de diciembre de 2015 por los contribuyentes aún no migrados.', '["No se requiere ninguna acción para este hito histórico -- se incluye como contexto de las entradas siguientes", "Si su empresa es anterior al despliegue de la facturación electrónica en Ecuador, tenga en cuenta que el requisito se amplió mediante resoluciones posteriores en 2018 y años siguientes -- vea los siguientes hitos"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-first-mandate-2014', 'de', 'Entschließung NAC-DGERCGC14-00790 führt die Echtzeitvalidierung der elektronischen Rechnungsstellung ein', 'Am 3. September 2014 (veröffentlicht am 2. Oktober 2014) erließ Ecuadors Servicio de Rentas Internas (SRI) die Entschließung NAC-DGERCGC14-00790, die das freiwillige Pilotprogramm von 2012 (Entschließung NAC-DGERCGC12-00105) durch eine echte, verbindliche Pflicht für designierte Steuerpflichtigengruppen ersetzte, elektronische Rechnungen im Moment der Transaktion selbst zur webservicebasierten Validierung an das SRI zu übermitteln. Dies ist der Ursprung von Ecuadors langjähriger Pflicht zur nahezu Echtzeit-E-Rechnung -- das alte System von 2012 durfte von noch nicht umgestellten Steuerpflichtigen nur bis zum 31. Dezember 2015 weiterverwendet werden.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er dient als Kontext für die folgenden Einträge", "Wenn Ihr Unternehmen älter ist als Ecuadors E-Rechnungs-Einführung, beachten Sie, dass sich die Pflicht durch weitere Entschließungen ab 2018 erweiterte -- siehe die folgenden Meilensteine"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-first-mandate-2014', 'fr', 'La résolution NAC-DGERCGC14-00790 introduit la validation de la facturation électronique en temps réel', 'Le 3 septembre 2014 (publiée le 2 octobre 2014), le Servicio de Rentas Internas (SRI) équatorien a émis la résolution NAC-DGERCGC14-00790, remplaçant le dispositif pilote volontaire de 2012 (résolution NAC-DGERCGC12-00105) par une obligation réelle et contraignante, pour des groupes désignés de contribuables, de transmettre les factures électroniques au SRI pour validation par service web au moment même de la transaction. C''est l''origine de l''obligation équatorienne de facturation électronique quasi en temps réel, en vigueur depuis lors -- l''ancien dispositif de 2012 est resté utilisable jusqu''au 31 décembre 2015 seulement pour les contribuables non encore migrés.', '["Aucune action n''est requise pour ce jalon historique -- il est fourni à titre de contexte pour les entrées suivantes", "Si votre entreprise est antérieure au déploiement de la facturation électronique en Équateur, notez que l''obligation s''est élargie par des résolutions ultérieures à partir de 2018 -- voir les jalons suivants"]');

-- ec-base-resolution-2018
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-base-resolution-2018', 'es', 'La Resolución NAC-DGERCGC18-00000233 sustituye a la de 2014 con el marco base de larga vigencia', 'El 22 de mayo de 2018 (publicada el 5 de junio de 2018), el SRI emitió la Resolución NAC-DGERCGC18-00000233, que sustituyó a la resolución de 2014 manteniendo el mismo principio de validación casi en tiempo real, y añadió una ventana de 72 horas para emisores de alto volumen. Esta se convirtió en la resolución base de larga vigencia, que el SRI fue modificando repetidamente hasta 2025 -- una actualización del marco técnico y procedimental, no en sí misma un cambio de a quién alcanza el mandato.', '["No se requiere ninguna acción para este hito histórico -- se incluye como contexto de las entradas siguientes", "Si su software de facturación se configuró conforme a las reglas de la resolución de 2014, confirme que también refleja la ventana de 72 horas introducida aquí"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-base-resolution-2018', 'de', 'Entschließung NAC-DGERCGC18-00000233 ersetzt die Entschließung von 2014 durch den langjährigen Rahmen', 'Am 22. Mai 2018 (veröffentlicht am 5. Juni 2018) erließ das SRI die Entschließung NAC-DGERCGC18-00000233, die die Entschließung von 2014 ersetzte, dabei aber denselben Grundsatz der Echtzeit-nahen Validierung beibehielt, und ergänzte eine 72-Stunden-Frist für Aussteller mit hohem Volumen. Dies wurde zur langjährigen Basisentschließung, die das SRI bis 2025 wiederholt änderte -- eine technisch-verfahrensrechtliche Aktualisierung des Rahmens, keine Änderung des Anwendungsbereichs an sich.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er dient als Kontext für die folgenden Einträge", "Wenn Ihre Rechnungssoftware nach den Regeln der Entschließung von 2014 konfiguriert wurde, prüfen Sie, ob sie auch die hier eingeführte 72-Stunden-Frist berücksichtigt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-base-resolution-2018', 'fr', 'La résolution NAC-DGERCGC18-00000233 remplace celle de 2014 par le cadre de base durable', 'Le 22 mai 2018 (publiée le 5 juin 2018), le SRI a émis la résolution NAC-DGERCGC18-00000233, remplaçant la résolution de 2014 tout en conservant le même principe de validation quasi en temps réel, et ajoutant un délai de 72 heures pour les émetteurs à fort volume. Celle-ci est devenue la résolution de base durable, que le SRI a modifiée à plusieurs reprises jusqu''en 2025 -- une mise à jour du cadre technique et procédural, et non en soi un changement du champ d''application.', '["Aucune action n''est requise pour ce jalon historique -- il est fourni à titre de contexte pour les entrées suivantes", "Si votre logiciel de facturation a été configuré selon les règles de la résolution de 2014, vérifiez qu''il tient aussi compte du délai de 72 heures introduit ici"]');

-- ec-universal-2022
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-universal-2022', 'es', 'La facturación electrónica alcanza una cobertura prácticamente universal', 'Al 29-30 de noviembre de 2022, el SRI había autorizado a 1.212.712 contribuyentes para la facturación electrónica, tras varias oleadas de despliegue obligatorio por sector y umbral entre 2020 y 2022 (maquinaria pesada y distribuidores de GLP en 2020, suministros B2G superiores a 1.000 USD en 2021, el régimen simplificado RIMPE creado el 1 de enero de 2022, y el tramo de ingresos de 200.000-300.000 USD en 2022). La cobertura es prácticamente universal salvo por una excepción: los contribuyentes RIMPE ''Negocios Populares'' (ingresos de hasta 20.000 USD) siguen exentos y pueden seguir utilizando ''notas de venta RISE'' en papel -- solo están realmente obligados a emitir facturas electrónicas los RIMPE ''Emprendedores'' (hasta 300.000 USD) y los contribuyentes de mayor tamaño.', '["Confirme en qué categoría RIMPE se encuentra su empresa -- Negocios Populares sigue exento, pero Emprendedores y categorías superiores deben emitir facturas electrónicas", "Si suministra bienes o servicios a contrapartes de Negocios Populares, no asuma que todo socio comercial ecuatoriano ya está en facturación electrónica"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-universal-2022', 'de', 'Die elektronische Rechnungsstellung erreicht eine praktisch flächendeckende Abdeckung', 'Bis zum 29./30. November 2022 hatte das SRI 1.212.712 Steuerpflichtige für die elektronische Rechnungsstellung freigegeben, nach mehreren sektor- und schwellenwertbasierten Pflicht-Wellen zwischen 2020 und 2022 (Schwermaschinen und LPG-Vertreiber 2020, B2G-Lieferungen über 1.000 USD 2021, das am 1. Januar 2022 geschaffene vereinfachte RIMPE-Regime, und die Einkommensklasse 200.000-300.000 USD 2022). Die Abdeckung ist praktisch flächendeckend, mit einer Ausnahme: RIMPE-Steuerpflichtige der Kategorie „Negocios Populares" (Einkommen bis 20.000 USD) bleiben befreit und dürfen weiterhin Papier-„notas de venta RISE" verwenden -- nur RIMPE „Emprendedores" (bis 300.000 USD) und größere Steuerpflichtige sind tatsächlich zur elektronischen Rechnungsstellung verpflichtet.', '["Prüfen Sie, welcher RIMPE-Kategorie Ihr Unternehmen angehört -- Negocios Populares bleibt befreit, aber Emprendedores und höhere Kategorien müssen elektronische Rechnungen ausstellen", "Wenn Sie Waren oder Dienstleistungen an Negocios-Populares-Gegenparteien liefern, gehen Sie nicht davon aus, dass jeder ecuadorianische Handelspartner bereits elektronisch abrechnet"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-universal-2022', 'fr', 'La facturation électronique atteint une couverture pratiquement universelle', 'Au 29-30 novembre 2022, le SRI avait autorisé 1 212 712 contribuables pour la facturation électronique, à la suite de plusieurs vagues de déploiement obligatoire par secteur et par seuil entre 2020 et 2022 (machines lourdes et distributeurs de GPL en 2020, fournitures B2G supérieures à 1 000 USD en 2021, le régime simplifié RIMPE créé le 1er janvier 2022, et la tranche de revenus de 200 000 à 300 000 USD en 2022). La couverture est pratiquement universelle, à l''exception d''un cas : les contribuables RIMPE « Negocios Populares » (revenus jusqu''à 20 000 USD) restent exemptés et peuvent continuer à utiliser des « notas de venta RISE » papier -- seuls les RIMPE « Emprendedores » (jusqu''à 300 000 USD) et les contribuables plus importants sont réellement tenus d''émettre des factures électroniques.', '["Vérifiez à quelle catégorie RIMPE appartient votre entreprise -- Negocios Populares reste exempté, mais Emprendedores et les catégories supérieures doivent émettre des factures électroniques", "Si vous fournissez des biens ou services à des contreparties Negocios Populares, ne présumez pas que tout partenaire commercial équatorien est déjà passé à la facturation électronique"]');

-- ec-emergency-relaxation-2024
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-emergency-relaxation-2024', 'es', 'El SRI concede una ventana temporal de 4 días hábiles para la transmisión en medio de la emergencia eléctrica nacional', 'El 5 de noviembre de 2024, en medio de la emergencia eléctrica nacional y la crisis de apagones de Ecuador, el SRI emitió la Resolución NAC-DGERCGC24-00000035, que flexibilizó la regla vigente de transmisión inmediata para permitir que los documentos electrónicos se transmitieran de forma inmediata, o dentro de un máximo de 4 días hábiles desde su generación. Esto se planteó explícitamente como una medida de alivio temporal ante la crisis energética, no como un endurecimiento adicional del mandato -- y se cerró poco más de un año después (véase el hito de enero de 2026).', '["Si su empresa se apoyó en la ventana de 4 días hábiles durante 2024-2025, confirme que sus procesos han vuelto a la transmisión inmediata -- vea el hito de enero de 2026", "No asuma que esta medida de alivio sigue vigente; fue una concesión temporal y específica de la crisis"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-emergency-relaxation-2024', 'de', 'SRI gewährt inmitten des nationalen Stromnotstands ein vorübergehendes Übermittlungsfenster von 4 Werktagen', 'Am 5. November 2024, inmitten von Ecuadors nationalem Stromnotstand und der Blackout-Krise, erließ das SRI die Entschließung NAC-DGERCGC24-00000035, die die geltende Regel der sofortigen Übermittlung lockerte und die Übermittlung elektronischer Dokumente sofort oder innerhalb von höchstens 4 Werktagen nach Erstellung erlaubte. Dies wurde ausdrücklich als vorübergehende Entlastungsmaßnahme angesichts der Energiekrise dargestellt, nicht als weitere Verschärfung der Pflicht -- und wurde etwas mehr als ein Jahr später wieder aufgehoben (siehe den Meilenstein vom Januar 2026).', '["Wenn sich Ihr Unternehmen 2024-2025 auf das 4-Werktage-Fenster verlassen hat, prüfen Sie, ob Ihre Prozesse inzwischen wieder auf sofortige Übermittlung umgestellt wurden -- siehe den Meilenstein vom Januar 2026", "Gehen Sie nicht davon aus, dass diese Entlastungsmaßnahme noch gilt; es handelte sich um eine vorübergehende, krisenspezifische Erleichterung"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-emergency-relaxation-2024', 'fr', 'Le SRI accorde un délai temporaire de 4 jours ouvrables pour la transmission en pleine urgence électrique nationale', 'Le 5 novembre 2024, en pleine urgence électrique nationale et crise des coupures de courant en Équateur, le SRI a émis la résolution NAC-DGERCGC24-00000035, assouplissant la règle en vigueur de transmission immédiate pour permettre la transmission des documents électroniques immédiatement, ou dans un délai maximal de 4 jours ouvrables suivant leur génération. Cette mesure a été explicitement présentée comme un allègement temporaire face à la crise énergétique, et non comme un nouveau durcissement de l''obligation -- elle a d''ailleurs été supprimée un peu plus d''un an plus tard (voir le jalon de janvier 2026).', '["Si votre entreprise s''est appuyée sur le délai de 4 jours ouvrables en 2024-2025, vérifiez que vos processus sont bien revenus à la transmission immédiate -- voir le jalon de janvier 2026", "Ne présumez pas que cette mesure d''allègement est toujours en vigueur ; il s''agissait d''une concession temporaire, propre à la crise"]');

-- ec-realtime-transmission-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-realtime-transmission-2026', 'es', 'La transmisión inmediata vuelve a ser obligatoria, cerrando la flexibilización de emergencia de 2024', 'A partir del 1 de enero de 2026, se eliminó la ventana de 4 días hábiles concedida en noviembre de 2024 durante la emergencia eléctrica, devolviendo a Ecuador a su regla base vigente de transmisión inmediata. El cambio debía entrar en vigor originalmente el 1 de agosto de 2025 conforme a la Resolución NAC-DGERCGC25-00000014 (que eliminó del Artículo 7 la frase ''o hasta dentro de un máximo de cuatro días hábiles de haberse generado el mismo''), pero la Resolución NAC-DGERCGC25-00000017 (29-30 de julio de 2025) postergó su fecha de vigencia al 1 de enero de 2026, dando a los contribuyentes unos cinco meses adicionales para adaptarse, y además acortó el plazo de la ventana de anulación del día 10 al día 7 del mes siguiente. Se trata de un endurecimiento genuino -- que cierra una flexibilización temporal de la era de la emergencia, no la introducción del reporte en tiempo real por primera vez, ya que la transmisión casi en tiempo real es la regla vigente en Ecuador desde 2014. Las facturas a ''consumidor final'' también dejaron de poder anularse desde esta fecha.', '["Confirme que sus sistemas de facturación vuelven a transmitir al SRI de forma inmediata, y no según la ya eliminada ventana de emergencia de 4 días hábiles", "Actualice sus flujos de anulación de facturas al nuevo plazo del día 7 del mes siguiente para los documentos a ''consumidor final''"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-realtime-transmission-2026', 'de', 'Die sofortige Übermittlung wird wieder verpflichtend -- die Lockerung von 2024 wird aufgehoben', 'Ab dem 1. Januar 2026 wurde die im November 2024 während des Stromnotstands gewährte 4-Werktage-Übermittlungsfrist gestrichen, wodurch Ecuador zu seiner geltenden Basisregel der sofortigen Übermittlung zurückkehrte. Die Änderung sollte ursprünglich am 1. August 2025 im Rahmen der Entschließung NAC-DGERCGC25-00000014 in Kraft treten (die den Satz „oder innerhalb einer Frist von höchstens vier Werktagen nach dessen Erstellung" aus Artikel 7 strich), doch die Entschließung NAC-DGERCGC25-00000017 (29./30. Juli 2025) verschob deren Inkrafttreten auf den 1. Januar 2026 und gab den Steuerpflichtigen damit rund fünf zusätzliche Monate zur Anpassung; zudem wurde die Frist für das Storno-Fenster vom 10. auf den 7. des Folgemonats verkürzt. Dies ist eine echte Verschärfung -- sie beendet eine vorübergehende Lockerung aus der Notstandszeit, führt aber nicht erstmals eine Echtzeit-Meldepflicht ein, da die nahezu Echtzeit-Übermittlung in Ecuador bereits seit 2014 die geltende Regel ist. Auch Rechnungen an „consumidor final" wurden ab diesem Datum unwiderruflich.', '["Prüfen Sie, ob Ihre Rechnungssysteme wieder sofort an das SRI übermitteln und nicht mehr das inzwischen gestrichene 4-Werktage-Notstandsfenster nutzen", "Aktualisieren Sie Ihre Stornierungsabläufe für Rechnungen auf die neue Frist zum 7. des Folgemonats für „consumidor final"-Dokumente"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-realtime-transmission-2026', 'fr', 'La transmission immédiate redevient obligatoire, mettant fin à l''assouplissement d''urgence de 2024', 'À compter du 1er janvier 2026, le délai de 4 jours ouvrables accordé en novembre 2024 pendant l''urgence électrique a été supprimé, ramenant l''Équateur à sa règle de base en vigueur de transmission immédiate. Le changement devait initialement entrer en vigueur le 1er août 2025 en vertu de la résolution NAC-DGERCGC25-00000014 (qui a supprimé de l''article 7 la phrase « ou dans un délai maximal de quatre jours ouvrables après sa génération »), mais la résolution NAC-DGERCGC25-00000017 (29-30 juillet 2025) a reporté sa date d''entrée en vigueur au 1er janvier 2026, accordant aux contribuables environ cinq mois supplémentaires pour s''adapter, et a également raccourci le délai de la fenêtre d''annulation du 10 au 7 du mois suivant. Il s''agit d''un véritable durcissement -- mettant fin à un assouplissement temporaire lié à l''urgence, et non de l''introduction d''une déclaration en temps réel pour la première fois, puisque la transmission quasi en temps réel est la règle en vigueur en Équateur depuis 2014. Les factures « consumidor final » sont également devenues non annulables à compter de cette date.', '["Vérifiez que vos systèmes de facturation transmettent de nouveau immédiatement au SRI, et non selon le délai d''urgence de 4 jours ouvrables désormais supprimé", "Mettez à jour vos processus d''annulation de factures avec la nouvelle échéance du 7 du mois suivant pour les documents « consumidor final »"]');

-- ec-traceability-decree-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-traceability-decree-2026', 'es', 'El Decreto Ejecutivo 398 moderniza la trazabilidad y autenticación de bienes y servicios', 'El 3 de junio de 2026, el gobierno de Ecuador emitió el Decreto Ejecutivo 398, que moderniza los mecanismos de trazabilidad y autenticación para bienes y determinados servicios. La cobertura de prensa (El Comercio) enmarca explícitamente el decreto como una construcción sobre el flujo continuo y en tiempo real de datos de facturación que ahora recibe el SRI -- desde que se restableció la transmisión inmediata en enero de 2026 -- para habilitar un seguimiento tributario continuo, en lugar del antiguo modelo de revisar los datos solo tras la presentación de declaraciones periódicas.', '["Esté atento a la normativa de desarrollo que precise a qué bienes y servicios se aplican los nuevos requisitos de trazabilidad", "Si su empresa maneja bienes sujetos a normas de trazabilidad, espere que el seguimiento por parte del SRI de sus datos de facturación sea más continuo, no solo puntual al momento de la declaración"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-traceability-decree-2026', 'de', 'Exekutivdekret 398 modernisiert Rückverfolgbarkeit und Authentifizierung für Waren und Dienstleistungen', 'Am 3. Juni 2026 erließ Ecuadors Regierung das Exekutivdekret 398, das Rückverfolgbarkeits- und Authentifizierungsmechanismen für Waren und bestimmte Dienstleistungen modernisiert. Die Presseberichterstattung (El Comercio) stellt das Dekret ausdrücklich als Weiterentwicklung des kontinuierlichen Echtzeit-Rechnungsdatenstroms dar, den das SRI seit der Wiederherstellung der sofortigen Übermittlung im Januar 2026 erhält, um eine fortlaufende Steuerüberwachung zu ermöglichen -- statt des älteren Modells, Daten erst nach Einreichung periodischer Erklärungen zu prüfen.', '["Achten Sie auf Durchführungsvorschriften, die festlegen, welche Waren und Dienstleistungen den neuen Rückverfolgbarkeitsanforderungen unterliegen", "Wenn Ihr Unternehmen Waren handhabt, die Rückverfolgbarkeitsregeln unterliegen, rechnen Sie mit einer kontinuierlicheren SRI-Überwachung Ihrer Rechnungsdaten, nicht nur punktuell bei der Erklärung"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ec-traceability-decree-2026', 'fr', 'Le décret exécutif 398 modernise la traçabilité et l''authentification des biens et services', 'Le 3 juin 2026, le gouvernement équatorien a émis le décret exécutif 398, modernisant les mécanismes de traçabilité et d''authentification pour les biens et certains services. La presse (El Comercio) présente explicitement ce décret comme s''appuyant sur le flux continu et en temps réel de données de facturation que le SRI reçoit désormais -- depuis le rétablissement de la transmission immédiate en janvier 2026 -- pour permettre un suivi fiscal continu, plutôt que l''ancien modèle consistant à n''examiner les données qu''après le dépôt des déclarations périodiques.', '["Surveillez les règlements d''application précisant quels biens et services relèvent des nouvelles exigences de traçabilité", "Si votre entreprise manipule des biens soumis aux règles de traçabilité, attendez-vous à un suivi plus continu de vos données de facturation par le SRI, et non plus seulement ponctuel au moment de la déclaration"]');
